/**
 * The Screen Time app-extension targets generated by this plugin.
 *
 * Each entry maps a target folder under the package's `targets/<name>/` directory
 * (which ships the Swift sources + Info.plist) to its bundle-id suffix (`slug`).
 *
 * The NSExtensionPointIdentifier / NSExtensionPrincipalClass live in each target's
 * checked-in `Info.plist` (copied verbatim), so they don't need to be repeated here.
 */
export interface ScreenTimeTarget {
  /** Folder under `targets/` and the Xcode target/product name. */
  name: string;
  /** Bundle-identifier suffix: `<mainAppBundleId>.<slug>`. */
  slug: string;
}

export const SCREEN_TIME_TARGETS: ScreenTimeTarget[] = [
  { name: 'ShieldConfigurationExtension', slug: 'shield-config' },
  { name: 'ShieldActionExtension', slug: 'shield-action' },
  { name: 'DeviceActivityMonitorExtension', slug: 'device-activity-monitor' },
  { name: 'DeviceActivityReportExtension', slug: 'device-activity-report' },
];

/** Minimum iOS version for the Screen Time extensions (FamilyControls/DeviceActivity need 16+). */
export const EXTENSION_DEPLOYMENT_TARGET = '16.0';
